"""Offline causal mutations of the actual immutable golden03 captures.

Fixtures are compressed actual captures, not a recreated simulation. The runtime
was a dirty-overlay snapshot of bee850c; these tests do not claim fresh native runs.
"""
import base64,copy,hashlib,importlib.util,json,pathlib,unittest,zlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
SPEC=importlib.util.spec_from_file_location('directional',ROOT/'tools/run_forest_directional_golden.py')
MODULE=importlib.util.module_from_spec(SPEC);SPEC.loader.exec_module(MODULE)
PAYLOAD=''
FIXTURE_SHA256='b194b9e9484349bc74c6853b03fc6d493699ea6cfe69037240969d6a9cd98388'

RAW=zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(RAW).hexdigest()==FIXTURE_SHA256
CAPTURES=json.loads(RAW)
class DirectionalValidatorTests(unittest.TestCase):
    def altered(self,variant='intended'):
        return copy.deepcopy(CAPTURES[variant])
    def rejected(self,data):
        self.assertTrue(MODULE.validate(data))
    def test_actual_four_captures(self):
        for variant,data in CAPTURES.items():
            with self.subTest(variant=variant):self.assertEqual(MODULE.validate(data),[])
    def test_delete_requests(self):
        for variant in ['intended','noH','onlyR']:
            data=self.altered(variant);data['requests']=[];self.rejected(data)
    def test_delete_events(self):
        for variant in CAPTURES:
            data=self.altered(variant);data['events']=[];self.rejected(data)
    def test_malformed_physical_payloads_fail_closed(self):
        data=self.altered();next(e for e in data['events'] if e['kind']=='hook_cast').pop('position');self.rejected(data)
        data=self.altered();next(e for e in data['events'] if e['kind']=='shot_fired')['direction']=None;self.rejected(data)
        data=self.altered('onlyR');data['danger_contacts'][0]=None;self.rejected(data)
    def test_minimal_motor_label_is_not_motion(self):
        data=self.altered();data['frames']=[{'motor_steps':1}];self.rejected(data)
    def test_delete_both_streams(self):
        data=self.altered();data['events']=[];data['requests']=[];self.rejected(data)
    @staticmethod
    def remove_ticks(data,removed):
        # Coherently retime every surviving stream; rejection must go beyond gaps.
        def tick(t):return t-sum(k<t for k in removed)
        for name in ['frames','events','requests','danger_contacts']:
            data[name]=[row for row in data[name] if row['tick'] not in removed]
            for row in data[name]:row['tick']=tick(row['tick'])
    def test_coherent_midpull_deletion(self):
        data=self.altered();start=next(e['tick'] for e in data['events'] if e['kind']=='hook_pull')
        self.remove_ticks(data,{start+2,start+3});self.rejected(data)
    def test_delete_return_and_keep_success_labels(self):
        data=self.altered();start=next(e['tick'] for e in data['events'] if e['kind']=='hook_cast' and e['position'][0]>350 and e['position'][1]>-100)
        self.remove_ticks(data,{f['tick'] for f in data['frames'] if f['tick']>=start});self.rejected(data)
    def test_delete_actual_shot_keep_body_burst(self):
        data=self.altered();data['events']=[e for e in data['events'] if e['kind']!='shot_fired'];self.rejected(data)
    def test_relabel_hook_target(self):
        data=self.altered();next(e for e in data['events'] if e['kind']=='hook_pull')['target']='crown_ring';self.rejected(data)
    def test_fake_kick_position(self):
        data=self.altered();next(e for e in data['events'] if e['kind']=='free')['position'][0]+=8;self.rejected(data)
    def test_coherent_whole_stream_resource_forgery(self):
        for energy,shots in [(True,False),(False,True),(True,True)]:
            data=self.altered()
            for frame in data['frames']:
                if energy:frame['energy']=100.0
                if shots:frame['shots']=2
            self.rejected(data)
    def test_airborne_free_energy_recovery(self):
        data=self.altered();shot=next(e['tick'] for e in data['events'] if e['kind']=='shot_fired')
        for frame in data['frames']:
            if frame['tick']>shot:frame['energy']+=1
        self.rejected(data)
    def test_fake_air_landing_cannot_justify_refunds(self):
        data=self.altered();second=[e for e in data['events'] if e['kind']=='hook_cast'][1]['tick']
        frame=data['frames'][second+6];self.assertFalse(frame['grounded']);frame['grounded']=True
        for f in data['frames'][second+6:second+20]:f['hook_used']=False
        self.rejected(data)
    def test_unbounded_energy(self):
        data=self.altered()
        for f in data['frames']:f['energy']=999999
        self.rejected(data)
    def test_air_shot_refill(self):
        data=self.altered();shot=next(e['tick'] for e in data['events'] if e['kind']=='shot_fired')
        data['frames'][shot]['shots']+=1;self.rejected(data)
    def test_premature_H_restoration(self):
        data=self.altered();pull=[e['tick'] for e in data['events'] if e['kind']=='hook_pull'][1]
        self.assertTrue(data['frames'][pull+1]['hook_used'])
        data['frames'][pull+1]['hook_used']=False;self.rejected(data)
    def test_hide_contact_records(self):
        for variant in ['noH','naivejump','onlyR']:
            data=self.altered(variant);data['danger_contacts']=[];self.rejected(data)
    def test_rewrite_geometry_to_hide_real_contacts(self):
        data=self.altered('onlyR');data['manifest']['dangers']=[];data['danger_contacts']=[];self.rejected(data)
    def test_coherent_recovery_step_deletion(self):
        data=self.altered('noH');platform=next(p for p in data['manifest']['platforms'] if p['id']=='recovery_step')
        removed={f['tick'] for f in data['frames'] if MODULE._support(f,platform)}
        self.assertGreaterEqual(len(removed),6);self.remove_ticks(data,removed);self.rejected(data)
    def test_fake_fallcatch_velocity(self):
        data=self.altered();cast=[e for e in data['events'] if e['kind']=='hook_cast'][3]
        data['frames'][cast['tick']-2]['velocity'][1]=0;self.rejected(data)
    def test_support_labels_cannot_replace_body_width(self):
        data=self.altered();platform=next(p for p in data['manifest']['platforms'] if p['id']=='crown')
        for frame in data['frames']:
            if MODULE._support(frame,platform):frame['position'][0]=platform['rect'][0]+1;frame['crown_support']=True
        self.rejected(data)
    def test_only_summary_success_is_not_recovery(self):
        data=self.altered('naivejump');data['frames']=data['frames'][:data['danger_contacts'][-1]['tick']]
        data['events']=[e for e in data['events'] if e['tick']<=len(data['frames'])];self.rejected(data)
if __name__=='__main__':unittest.main()
